default=json.loads((A/'default-physical-result.json').read_text());physical=json.loads((A/'native-physical-result.json').read_text());new=[r for r in numerical if r['case']=='corrected-original' or r['case'].startswith('corrected-free-')]
report=dict(schema='crow-quality-adjacent-refinement-study-v1',source_commit='abad6a82',numerical_cases=5,numerical_corrected_accepted=sum(r['code']==0 for r in new),independent_accepted_residual_max=max(r['independent_scaled_optimality'] for r in new),numerical_old_accepted=sum(r['code']==0 for r in numerical if r['case']=='old-expanded' or r['case'].startswith('old-free-')),legacy_scratch_capture_exact=numerical[1]['capture_exact'],physical_regression_records=sum(r['records'] for r in physical),physical_regressions_exact=all(r['physical_exact'] for r in physical),default_physical_files=len(default),default_physical_files_exact=all(r['byte_exact'] for r in default),crow=crow,chunk_first_failure_capture_exact=crow[1]['capture_sha256']==crow[2]['capture_sha256'],accepted_coupled_control_transitions=0,first_failed_substep_before=2,first_failed_substep_after=7,full_release_build_passed=True,owner_checks_passed=['constraint IR','native world contact'],performance_limit='Single cold invocation timings are retained; no general throughput improvement claimed. Refinement adds bounded work only after otherwise-rejected small solves.',known_preexisting_issue='evaluateState does not initialize impulses in uncovered capacity-padding rows. All captured padding impulses/J/bias are zero here; no attribution or fix is claimed.',preflight_failure='Initial warm-plan preparation referenced nonexistent build/lib/metalrobo/MetalRobo.metallib. It failed before any native command; corrected to actual build/shaders/MetalRobo.metallib before sealing native plan.',limits='Exposed engineering fixture, one retained problem and four predeclared numerical variants; no ecological generalization or complete crow qualification.',policy_or_profile_promoted=False,goal_complete=False)
